36	/// The CPF grant flags, in numeric order.
37	fn cpf_flags() -> [(&'static str, u32); 8] {
38	    [
39	        ("CPF_READ", grant::CPF_READ),
40	        ("CPF_WRITE", grant::CPF_WRITE),
41	        ("CPF_TRY", grant::CPF_TRY),
42	        ("CPF_USED", grant::CPF_USED),
