49	
50	/// An arbitrary `(idx, seq)` pair and its packed id, used by the header's
51	/// round-trip `_Static_assert`s. Both fields are non-zero and unequal, so a
52	/// macro that dropped or swapped one would fail the check.
53	const GRANT_PROBE_IDX: u32 = 1234;
54	const GRANT_PROBE_SEQ: u32 = 56;
55	const GRANT_PROBE_ID: i32 = grant::grant_id(GRANT_PROBE_IDX, GRANT_PROBE_SEQ);
56	
57	/// A server request band: base constant, its members, and the count constant
58	/// that bounds it (`None` for VM, which has no `NR_*` on the Rust side).
59	///
60	/// `members` is checked against `count` by
61	/// `every_band_member_list_matches_its_count`: a new request that bumps the Rust
62	/// `NR_*` without gaining a row here would otherwise render a larger count and
63	/// no macro for the request itself.
64	struct Band {
65	    title: &'static str,
66	    base_name: &'static str,
67	    base: i32,
68	    count: Option<(&'static str, usize)>,
69	    members: Vec<(&'static str, i32)>,
70	}
71	
72	/// The bands, in ascending numeric order — `bands_are_in_ascending_numeric_order`
73	/// enforces that, so inserting a new band in the wrong place fails a test rather
74	/// than rendering a header whose sections disagree with its ordering asserts.
75	fn bands() -> [Band; 6] {
76	    [
77	        Band {
78	            title: "PM requests",
79	            base_name: "PM_RQ_BASE",
80	            base: callnr::PM_RQ_BASE,
81	            count: Some(("NR_PM_MSGS", callnr::NR_PM_MSGS)),
82	            members: vec![
83	                ("PM_GETPID", callnr::PM_GETPID),
84	                ("PM_FORK", callnr::PM_FORK),
85	                ("PM_EXIT", callnr::PM_EXIT),
86	                ("PM_WAIT", callnr::PM_WAIT),
87	                ("PM_EXEC", callnr::PM_EXEC),
88	                ("PM_GRANT_TEST", callnr::PM_GRANT_TEST),
89	            ],
90	        },
91	        Band {
92	            title: "character-device requests",
93	            base_name: "CDEV_RQ_BASE",
94	            base: callnr::CDEV_RQ_BASE,
95	            count: Some(("NR_CDEV_MSGS", callnr::NR_CDEV_MSGS)),
96	            members: vec![("CDEV_WRITE", callnr::CDEV_WRITE)],
97	        },
98	        Band {
99	            title: "VM requests",
100	            base_name: "VM_RQ_BASE",
101	            base: callnr::VM_RQ_BASE,
102	            count: None,
103	            members: vec![
104	                ("VM_PAGEFAULT", callnr::VM_PAGEFAULT),
105	                ("VM_BRK", callnr::VM_BRK),
106	                ("VM_MMAP", callnr::VM_MMAP),
107	                ("VM_MUNMAP", callnr::VM_MUNMAP),
108	                ("VM_FORK", callnr::VM_FORK),
109	            ],
110	        },
111	        Band {
112	            title: "SEF control messages",
113	            base_name: "SEF_RQ_BASE",
114	            base: callnr::SEF_RQ_BASE,
115	            count: Some(("NR_SEF_MSGS", callnr::NR_SEF_MSGS)),
116	            members: vec![
117	                ("SEF_INIT", callnr::SEF_INIT),
118	                ("SEF_SIGNAL", callnr::SEF_SIGNAL),
119	            ],
120	        },
121	        Band {
122	            title: "DS requests",
123	            base_name: "DS_RQ_BASE",
