142	            ],
143	        },
144	    ]
145	}
146	
147	/// Render `minix/callnr.h`.
148	pub fn render() -> String {
149	    let mut f = CFile::new(
150	        "Kernel-call numbers, server request bands, and their payload constants.",
151	        &["kernel-shared/src/callnr.rs"],
152	    );
153	    f.guard_open(GUARD);
154	
155	    f.blank();
156	    f.include(
157	        "minix/ipc.h",
158	        "NOTIFY_MESSAGE, for the band ordering checks",
159	    );
160	
161	    f.block_comment(&[
162	        "Deviation from MINIX 3: its <minix/callnr.h> holds POSIX syscall numbers",
163	        "and keeps server request numbers in <minix/com.h>. minix.rs has no POSIX",
164	        "call-number layer -- a libc wrapper builds a server request directly --",
165	        "so this header carries the kernel calls and the request bands together.",
166	        "",
167	        "Payload byte offsets are not emitted yet: on the Rust side they live in",
168	        "doc comments rather than constants. The first musl wrapper (slice 5.6) is",
169	        "the forcing function for promoting them to real constants.",
170	    ]);
171	
172	    f.section("kernel calls");
173	    f.define_hex("KERNEL_CALL", callnr::KERNEL_CALL.into());
174	    f.blank();
175	    for (name, value) in kernel_calls() {
176	        f.define_hex(name, value.into());
177	    }
178	    f.blank();
179	    // Name-matched with the Rust constant as of slice 5.1 (it was
180	    // `NR_KERN_CALLS_PHASE4` there, and carried a provenance comment here to
181	    // bridge the gap). Keep the two spellings identical past the 5.6 ABI
182	    // freeze — `nr_kern_calls_is_not_phase_suffixed` guards it.
183	    f.define_dec("NR_KERN_CALLS", callnr::NR_KERN_CALLS as i64);
184	    f.define_dec("NR_SYS_CALLS", callnr::NR_SYS_CALLS as i64);
185	
186	    f.section("kernel-call payload constants");
187	    f.define_dec("GET_WHOAMI", callnr::GET_WHOAMI.into());
188	    f.define_dec("SYS_GETINFO_NAME_LEN", callnr::SYS_GETINFO_NAME_LEN as i64);
189	    f.define_dec("EXEC_NAME_LEN", callnr::EXEC_NAME_LEN as i64);
190	    f.define_dec("PRIVCTL_SET_USER", callnr::PRIVCTL_SET_USER.into());
191	    f.define_dec("SCHEDCTL_FLAG_KERNEL", callnr::SCHEDCTL_FLAG_KERNEL.into());
192	
193	    f.section("SYS_DIAGCTL subcodes + inline-text payload");
194	    f.define_dec("DIAGCTL_CODE_DIAG", callnr::DIAGCTL_CODE_DIAG.into());
195	    f.define_dec(
196	        "DIAGCTL_CODE_STACKTRACE",
197	        callnr::DIAGCTL_CODE_STACKTRACE.into(),
198	    );
199	    f.define_dec(
200	        "DIAGCTL_CODE_REGISTER",
201	        callnr::DIAGCTL_CODE_REGISTER.into(),
202	    );
203	    f.define_dec(
204	        "DIAGCTL_CODE_UNREGISTER",
205	        callnr::DIAGCTL_CODE_UNREGISTER.into(),
206	    );
207	    f.define_dec("DIAG_TEXT_OFF", callnr::DIAG_TEXT_OFF as i64);
208	    f.define_dec("DIAG_TEXT_MAX", callnr::DIAG_TEXT_MAX as i64);
209	
210	    f.section("grants: SYS_SETGRANT / SYS_SAFECOPY");
211	    f.block_comment(&[
212	        "The grant ABI (slice 5.2). The grant-entry layout itself is deliberately",
213	        "not emitted yet: no C consumes it before the musl slice, and a dedicated",
214	        "<minix/safecopies.h> would need its own builder and CI syntax check. The",
215	        "flag values and the id packing are here because a C caller needs them to",
216	        "read a grant id out of a message payload.",
217	    ]);
218	    f.define_dec("SAFECOPY_FROM", callnr::SAFECOPY_FROM.into());
219	    f.define_dec("SAFECOPY_TO", callnr::SAFECOPY_TO.into());
220	    f.blank();
221	    for (name, value) in cpf_flags() {
222	        f.define_hex(name, value.into());
223	    }
224	    f.blank();
225	    f.define_dec("GRANT_SHIFT", grant::GRANT_SHIFT.into());
226	    f.define_hex("GRANT_MAX_IDX", grant::GRANT_MAX_IDX.into());
227	    f.define_hex("GRANT_MAX_SEQ", grant::GRANT_MAX_SEQ.into());
228	    f.define_dec("GRANT_INVALID", grant::GRANT_INVALID.into());
229	    f.blank();
230	    f.define_raw(
231	        "GRANT_ID(idx, seq)",
232	        "((int) ((((unsigned) (seq) & GRANT_MAX_SEQ) << GRANT_SHIFT) \\\n                                 | ((unsigned) (idx) & GRANT_MAX_IDX)))",
233	    );
234	    f.define_raw("GRANT_IDX(g)", "((unsigned) (g) & GRANT_MAX_IDX)");
235	    f.define_raw(
236	        "GRANT_SEQ(g)",
237	        "(((unsigned) (g) >> GRANT_SHIFT) & GRANT_MAX_SEQ)",
238	    );
239	    f.define_raw("GRANT_VALID(g)", "((g) >= 0)");
240	    f.blank();
241	    // Check the C packing against the Rust one rather than trusting that the
242	    // two expressions were transcribed the same way.
243	    f.static_assert(
244	        &format!(
245	            "GRANT_ID(GRANT_MAX_IDX, GRANT_MAX_SEQ) == {}",
246	            grant::grant_id(grant::GRANT_MAX_IDX, grant::GRANT_MAX_SEQ)
247	        ),
248	        "the C grant-id packing disagrees with the Rust one",
249	    );
250	    f.static_assert(
251	        &format!("GRANT_IDX({GRANT_PROBE_ID}) == {GRANT_PROBE_IDX}"),
252	        "GRANT_IDX does not invert GRANT_ID",
253	    );
254	    f.static_assert(
255	        &format!("GRANT_SEQ({GRANT_PROBE_ID}) == {GRANT_PROBE_SEQ}"),
256	        "GRANT_SEQ does not invert GRANT_ID",
257	    );
258	
259	    f.section("SYS_VMCTL subcalls");
260	    f.define_dec("VMCTL_PT_MAP", callnr::VMCTL_PT_MAP.into());
261	    f.define_dec("VMCTL_PT_UNMAP", callnr::VMCTL_PT_UNMAP.into());
262	    f.define_dec(
263	        "VMCTL_CLEAR_PAGEFAULT",
264	        callnr::VMCTL_CLEAR_PAGEFAULT.into(),
265	    );
266	    f.define_dec("VMCTL_GET_PAGEFAULT", callnr::VMCTL_GET_PAGEFAULT.into());
267	    f.define_dec("VMCTL_VMINHIBIT_SET", callnr::VMCTL_VMINHIBIT_SET.into());
268	    f.define_dec(
269	        "VMCTL_VMINHIBIT_CLEAR",
270	        callnr::VMCTL_VMINHIBIT_CLEAR.into(),
271	    );
272	    f.define_dec("NR_VMCTL_SUBCALLS", callnr::NR_VMCTL_SUBCALLS as i64);
273	    f.blank();
274	    f.define_dec("VMCTL_PROT_WRITE", callnr::VMCTL_PROT_WRITE.into());
275	    f.define_dec("VMCTL_PROT_EXEC", callnr::VMCTL_PROT_EXEC.into());
276	
277	    for band in bands() {
278	        f.section(band.title);
279	        f.define_hex(band.base_name, band.base.into());
280	        for (name, value) in &band.members {
281	            f.define_hex(name, (*value).into());
282	        }
283	        if let Some((count_name, count)) = band.count {
284	            f.define_dec(count_name, count as i64);
285	        }
286	    }
287	
288	    f.section("band ordering");
289	    f.block_comment(&[
290	        "Mirrors the `const _: () = assert!(..)` guards in callnr.rs: every band",
291	        "sits above the previous one and entirely below NOTIFY_MESSAGE, so no",
292	        "server request can ever be mistaken for a kernel NOTIFY.",
293	    ]);
294	    f.static_assert(
295	        "NR_SYS_CALLS >= NR_KERN_CALLS",
296	        "the privilege call mask is narrower than the kernel-call set",
297	    );
298	    f.static_assert(
299	        "PM_RQ_BASE > KERNEL_CALL + NR_KERN_CALLS - 1",
300	        "the PM band overlaps the kernel calls",
301	    );
302	    f.static_assert(
303	        "PM_RQ_BASE + NR_PM_MSGS - 1 < CDEV_RQ_BASE",
304	        "the PM band overlaps the CDEV band",
305	    );
306	    f.static_assert(
307	        "CDEV_RQ_BASE + NR_CDEV_MSGS - 1 < VM_RQ_BASE",
308	        "the CDEV band overlaps the VM band",
309	    );
310	    f.static_assert("SEF_RQ_BASE > VM_FORK", "the SEF band overlaps the VM band");
311	    f.static_assert(
312	        "DS_RQ_BASE > SEF_RQ_BASE + NR_SEF_MSGS - 1",
313	        "the DS band overlaps the SEF band",
314	    );
315	    f.static_assert(
316	        "SCHED_RQ_BASE > DS_RQ_BASE + NR_DS_REQUESTS - 1",
317	        "the SCHED band overlaps the DS band",
318	    );
319	    f.static_assert(
320	        "SCHED_RQ_BASE + NR_SCHED_MSGS - 1 < NOTIFY_MESSAGE",
321	        "a server request number collides with NOTIFY_MESSAGE",
322	    );
323	
324	    f.guard_close(GUARD);
325	    f.finish()
326	}
327	
328	#[cfg(test)]
329	mod tests {
330	    use super::*;
331	    use crate::builder;
332	
333	    #[test]
334	    fn kernel_calls_render_from_live_constants() {
335	        let text = render();
336	        for (name, value) in kernel_calls() {
337	            assert_eq!(
338	                builder::define_value(&text, name).as_deref(),
339	                Some(format!("0x{value:X}").as_str()),
340	                "{name} did not render from its Rust constant"
341	            );
342	        }
343	    }
344	
345	    #[test]
346	    fn the_kernel_call_list_is_complete_and_contiguous() {
347	        let calls = kernel_calls();
348	        assert_eq!(calls.len(), callnr::NR_KERN_CALLS);
349	        for (i, (name, value)) in calls.into_iter().enumerate() {
350	            assert_eq!(
351	                value,
352	                callnr::KERNEL_CALL + i as i32,
353	                "{name} is out of order"
354	            );
355	        }
356	    }
357	
358	    #[test]
359	    fn every_band_base_member_and_count_appears() {
360	        let text = render();
361	        for band in bands() {
362	            assert_eq!(
363	                builder::define_value(&text, band.base_name).as_deref(),
364	                Some(format!("0x{:X}", band.base).as_str())
365	            );
366	            for (name, value) in &band.members {
367	                assert_eq!(
368	                    builder::define_value(&text, name).as_deref(),
369	                    Some(format!("0x{value:X}").as_str()),
370	                    "{name} missing from the {} band",
371	                    band.title
372	                );
373	            }
374	            if let Some((count_name, count)) = band.count {
375	                assert_eq!(
376	                    builder::define_value(&text, count_name).as_deref(),
377	                    Some(count.to_string().as_str())
378	                );
379	            }
380	        }
381	    }
382	
383	    /// The completeness half of the band lock: `every_band_base_member_and_count_appears`
384	    /// only proves that whatever is listed renders, so on its own a new request
385	    /// that bumped `NR_PM_MSGS` would grow the C count and the ordering asserts
386	    /// while silently omitting its own macro. Each band's members must therefore
387	    /// be exactly `count` entries, contiguous from `base`.
388	    #[test]
389	    fn every_band_member_list_matches_its_count() {
390	        for band in bands() {
391	            if let Some((count_name, count)) = band.count {
392	                assert_eq!(
393	                    band.members.len(),
394	                    count,
395	                    "the {} band lists {} members but {count_name} is {count}",
396	                    band.title,
397	                    band.members.len()
398	                );
399	            }
400	            for (i, (name, value)) in band.members.iter().enumerate() {
401	                assert_eq!(
402	                    *value,
403	                    band.base + i as i32,
404	                    "{name} is out of order in the {} band",
405	                    band.title
406	                );
407	            }
408	        }
409	    }
410	
411	    /// The header renders one section per band in `bands()` order, and the
412	    /// ordering `_Static_assert`s below them chain each band to the previous one.
413	    /// A band inserted in the wrong slot would therefore render sections that
414	    /// disagree with the asserts — so pin the order here rather than in review.
415	    /// Slices 5.4 (VFS, `0x800`), 5.7 (BDEV, `0x900`), and 5.8 (MFS, `0xA00`)
416	    /// each insert a band *below* CDEV; this test is what tells them where.
417	    #[test]
418	    fn bands_are_in_ascending_numeric_order() {
419	        let bands = bands();
420	        for pair in bands.windows(2) {
421	            let (lo, hi) = (&pair[0], &pair[1]);
422	            let lo_last = lo.members.last().map(|(_, v)| *v).unwrap_or(lo.base);
423	            assert!(
424	                lo_last < hi.base,
425	                "the {} band (ends {lo_last:#x}) is not below the {} band ({:#x})",
426	                lo.title,
427	                hi.title,
428	                hi.base,
429	            );
430	        }
431	    }
432	
433	    /// The CDEV band's payload offsets and `CDEV_MAX_IO` are deliberately not
434	    /// emitted: this header's own comment defers every payload offset to the first
435	    /// musl wrapper (slice 5.6), and musl's `write()` goes to VFS, not straight to
436	    /// a character driver — so no C in Phase 5 needs them.
437	    #[test]
438	    fn no_cdev_payload_constants_are_emitted_yet() {
439	        let text = render();
440	        assert_eq!(
441	            builder::define_value(&text, "CDEV_WRITE").as_deref(),
442	            Some(format!("0x{:X}", callnr::CDEV_WRITE).as_str())
443	        );
444	        for name in [
445	            "CDEV_MINOR_OFF",
446	            "CDEV_GRANT_OFF",
447	            "CDEV_LEN_OFF",
448	            "CDEV_OFFSET_OFF",
449	            "CDEV_MAX_IO",
450	            "CDEV_MINOR_CONSOLE",
451	        ] {
452	            assert!(
453	                builder::define_value(&text, name).is_none(),
454	                "{name} must wait for the musl slice"
455	            );
456	        }
457	    }
458	
459	    /// VM is the one band with no `NR_*` count on the Rust side, so its guard
460	    /// names the last member instead. Pin both the guard text and the member the
461	    /// guard names, so a future `NR_VM_MSGS` — or a `VM_RQ_BASE + 5` request —
462	    /// is a deliberate change here rather than a silent gap.
463	    #[test]
464	    fn the_vm_band_has_no_count_constant() {
465	        let vm = bands()
466	            .into_iter()
467	            .find(|b| b.base_name == "VM_RQ_BASE")
468	            .unwrap();
469	        assert!(vm.count.is_none());
470	        assert_eq!(
471	            vm.members.last().map(|(name, value)| (*name, *value)),
472	            Some(("VM_FORK", callnr::VM_FORK)),
473	            "the SEF ordering assert names the VM band's last member"
474	        );
475	        assert!(render().contains("SEF_RQ_BASE > VM_FORK"));
476	    }
477	
478	    #[test]
479	    fn grant_constants_render_from_live_constants() {
480	        let text = render();
481	        for (name, value) in cpf_flags() {
482	            assert_eq!(
483	                builder::define_value(&text, name).as_deref(),
484	                Some(format!("0x{value:X}").as_str()),
485	                "{name} did not render from its Rust constant"
486	            );
487	        }
488	        assert_eq!(
489	            builder::define_value(&text, "GRANT_SHIFT").as_deref(),
490	            Some(grant::GRANT_SHIFT.to_string().as_str())
491	        );
492	        assert_eq!(
493	            builder::define_value(&text, "GRANT_MAX_IDX").as_deref(),
494	            Some(format!("0x{:X}", grant::GRANT_MAX_IDX).as_str())
495	        );
496	        assert_eq!(
497	            builder::define_value(&text, "GRANT_MAX_SEQ").as_deref(),
498	            Some(format!("0x{:X}", grant::GRANT_MAX_SEQ).as_str())
499	        );
500	        // Negative values render parenthesized, so a `-1` cannot be pasted into
501	        // a larger expression and change its meaning.
502	        assert_eq!(
503	            builder::define_value(&text, "GRANT_INVALID").as_deref(),
504	            Some("(-1)")
505	        );
506	    }
507	
508	    /// The C grant-id macros are a second implementation of the Rust packing, so
509	    /// the header carries `_Static_assert`s tying them together. Check the
510	    /// asserted values come from the Rust helpers rather than being transcribed.
511	    #[test]
512	    fn the_grant_id_macro_asserts_use_rust_computed_values() {
513	        let text = render();
514	        let max = grant::grant_id(grant::GRANT_MAX_IDX, grant::GRANT_MAX_SEQ);
515	        assert!(text.contains(&format!("GRANT_ID(GRANT_MAX_IDX, GRANT_MAX_SEQ) == {max}")));
516	        assert!(text.contains(&format!("GRANT_IDX({GRANT_PROBE_ID}) == {GRANT_PROBE_IDX}")));
517	        assert!(text.contains(&format!("GRANT_SEQ({GRANT_PROBE_ID}) == {GRANT_PROBE_SEQ}")));
518	        // The probe must actually exercise both fields.
519	        assert_eq!(grant::grant_idx(GRANT_PROBE_ID), GRANT_PROBE_IDX);
520	        assert_eq!(grant::grant_seq(GRANT_PROBE_ID), GRANT_PROBE_SEQ);
521	        assert_ne!(GRANT_PROBE_IDX, GRANT_PROBE_SEQ);
522	    }
523	
524	    #[test]
525	    fn safecopy_selectors_render_from_live_constants() {
526	        let text = render();
527	        assert_eq!(
528	            builder::define_value(&text, "SAFECOPY_FROM").as_deref(),
529	            Some(callnr::SAFECOPY_FROM.to_string().as_str())
530	        );
531	        assert_eq!(
532	            builder::define_value(&text, "SAFECOPY_TO").as_deref(),
533	            Some(callnr::SAFECOPY_TO.to_string().as_str())
534	        );
535	    }
536	
537	    /// `GrantEntry` is deliberately not emitted as a C struct until a C caller
538	    /// needs it (slice 5.6). Nothing may quietly add one here — that belongs in
539	    /// its own `<minix/safecopies.h>` with its own CI syntax check.
540	    #[test]
541	    fn no_grant_struct_is_emitted_yet() {
542	        let text = render();
543	        assert!(!text.contains("cp_grant_entry"));
544	        assert!(!text.contains("struct "));
545	    }
546	
547	    /// The C name and the Rust name must stay identical. The Rust constant was
548	    /// `NR_KERN_CALLS_PHASE4` until slice 5.1, which renamed it to match this
549	    /// header rather than let a phase-scoped name outlive Phase 4 and cross the
550	    /// slice-5.6 ABI freeze. Nothing may reintroduce a phase suffix on either
551	    /// side.
552	    #[test]
553	    fn nr_kern_calls_is_not_phase_suffixed() {
554	        let text = render();
555	        assert_eq!(
556	            builder::define_value(&text, "NR_KERN_CALLS").as_deref(),
557	            Some(callnr::NR_KERN_CALLS.to_string().as_str())
558	        );
559	        assert!(
560	            !text.contains("PHASE"),
561	            "the ABI header must carry no phase-scoped names"
562	        );
563	    }
564	}
