        &format!("GRANT_IDX({GRANT_PROBE_ID}) == {GRANT_PROBE_IDX}"),
        "GRANT_IDX does not invert GRANT_ID",
    );
    f.static_assert(
        &format!("GRANT_SEQ({GRANT_PROBE_ID}) == {GRANT_PROBE_SEQ}"),
        "GRANT_SEQ does not invert GRANT_ID",
    );

