                // Parent: reap the child (blocks until it exits), then loop to
                // fork the next one.
                let mut w = pm_msg(PM_WAIT);
                let _ = ipc_sendrec(pm, &mut w);
            }
            _ => {
                // Transient fork failure (table full): back off briefly, retry.
                for _ in 0..1024 {
                    core::hint::spin_loop()
                }
            }
        }
    }
}

