275	mod tests {
276	    use super::*;
277	    use minixrs_kernel_shared::grant::{CPF_READ, CPF_WRITE};
278	
279	    const CAP: usize = 4;
280	
281	    fn table() -> [GrantEntry; CAP] {
282	        [GrantEntry::EMPTY; CAP]
283	    }
284	
285	    fn direct(
286	        t: &mut [GrantEntry; CAP],
287	        seq: &mut u32,
288	        who_to: Endpoint,
289	        addr: u64,
290	        len: u64,
291	    ) -> Result<i32, i32> {
