302	    fn allocation_fills_the_entry_the_kernel_will_read() {
303	        let mut t = table();
304	        let mut seq = 0;
305	        let gid = direct(&mut t, &mut seq, 7, 0x1000, 64).expect("slot available");
306	        let e = t[grant_idx(gid) as usize];
307	        assert_eq!(e.flags & CPF_USED, CPF_USED);
308	        assert_eq!(e.flags & CPF_VALID, CPF_VALID);
309	        assert_eq!(e.flags & CPF_DIRECT, CPF_DIRECT);
310	        assert_eq!(e.flags & CPF_READ, CPF_READ);
311	        assert_eq!(e.who_to, 7);
312	        assert_eq!(e.who_from, NONE);
313	        assert_eq!(e.addr, 0x1000);
314	        assert_eq!(e.len, 64);
315	        // The id must name this slot at this generation, or the kernel's
316	        // sequence check rejects a perfectly good grant.
317	        assert_eq!(e.seq, grant_seq(gid));
318	    }
