320	    #[test]
321	    fn magic_grants_record_the_third_party() {
322	        let mut t = table();
323	        let mut seq = 0;
324	        let gid = alloc_grant_in(&mut t, &mut seq, CPF_MAGIC | CPF_READ, 7, 10, 0x10_0000, 8)
325	            .expect("slot available");
326	        let e = t[grant_idx(gid) as usize];
327	        assert_eq!(e.flags & CPF_MAGIC, CPF_MAGIC);
328	        assert_eq!(e.flags & CPF_DIRECT, 0);
