332	    #[test]
333	    fn access_bits_are_recorded_exactly_as_requested() {
334	        // The kernel tests `flags & access == access`, so a read-only grant must
335	        // not carry the write bit — and a read/write grant must carry both.
336	        let mut t = table();
337	        let mut seq = 0;
338	        let ro = direct(&mut t, &mut seq, 1, 0x1000, 8).unwrap();
339	        assert_eq!(t[grant_idx(ro) as usize].flags & CPF_WRITE, 0);
