356	    #[test]
357	    fn successive_grants_take_distinct_slots_and_sequences() {
358	        let mut t = table();
359	        let mut seq = 0;
360	        let a = direct(&mut t, &mut seq, 1, 0x1000, 8).unwrap();
361	        let b = direct(&mut t, &mut seq, 2, 0x2000, 8).unwrap();
362	        assert_ne!(grant_idx(a), grant_idx(b));
