368	    fn malformed_requests_are_rejected_before_a_slot_is_taken() {
369	        let mut t = table();
370	        let mut seq = 0;
371	        assert_eq!(direct(&mut t, &mut seq, 1, 0, 8), Err(EINVAL)); // NULL
