414	        // The whole point of the sequence field. Revoke, re-grant into the same
415	        // slot, and the old id must not be a valid name for the new grant.
416	        let mut t = table();
417	        let mut seq = 0;
418	        let old = direct(&mut t, &mut seq, 1, 0x1000, 8).unwrap();
419	        revoke_in(&mut t, old).unwrap();
420	        let new = direct(&mut t, &mut seq, 2, 0x2000, 8).unwrap();
421	        assert_eq!(grant_idx(old), grant_idx(new), "same slot reused");
422	        assert_ne!(old, new);
423	        assert_ne!(t[grant_idx(new) as usize].seq, grant_seq(old));
424	        // And the stale id cannot revoke the new grant either.
425	        assert_eq!(revoke_in(&mut t, old), Err(EINVAL));
426	        assert_eq!(used_in(&t), 1);
