438	        let mut t = table();
439	        let mut seq = GRANT_MAX_SEQ;
440	        let gid = direct(&mut t, &mut seq, 1, 0x1000, 8).unwrap();
441	        assert_eq!(grant_seq(gid), GRANT_MAX_SEQ);
442	        assert!(grant_valid(gid));
443	        assert_eq!(seq, 0, "the sequence must wrap, not overflow the field");
444	    }
445	
446	    #[test]
447	    fn a_new_pool_is_unregistered_and_empty() {
448	        let pool: GrantPool<CAP> = GrantPool::new();
449	        assert_eq!(pool.used(), 0);
450	        assert_eq!(
451	            pool.registered_at, 0,
452	            "no kernel call before the first grant"
453	        );
454	    }
455	}
