    #[test]
    fn a_negative_descriptor_is_ebadf() {
        // A client that passed through an errno by mistake, or a wrapped count.
        for fd in [-1i32, -3, i32::MIN] {
            assert_eq!(resolve(0, fd), Err(EBADF), "fd {fd}");
        }
    }

