    fn an_empty_table_resolves_nothing() {
        // Degenerate borrow: no rows at all. `resolve_in` must answer `EBADF`
        // rather than index into a zero-length slice.
        assert_eq!(resolve_in(&[], 0, 1), Err(EBADF));
    }
}

