/// Drive `CDEV_WRITE` until `len` bytes are out, and report the total.
///
/// A character driver may write fewer bytes than asked (`CDEV_MAX_IO`), which is
/// how it stages through a small buffer with no allocator. That is a *driver*
/// detail, and POSIX `write()` is not allowed to expose it, so the loop re-sends
/// with `offset` advanced. One grant covers the whole buffer; only the offset
/// moves.
///
/// Two ways out other than completion:
///
///   - **An error after partial progress reports the progress.** POSIX's rule: a
///     partial success beats an error, because the bytes really did go out and the
///     caller must not send them twice. The error surfaces on the caller's next
///     write, which is where it is still true.
///   - **A driver that reports zero ends the loop.** No progress means re-sending
///     the same request forever, and a server that spins is worse than a short
///     write.
#[cfg_attr(test, allow(dead_code))]
fn write_all(tty: Endpoint, minor: i32, gid: i32, len: usize) -> i32 {
    let mut off = 0usize;
    while off < len {
        let n = cdev_write(tty, minor, gid, (len - off) as i32, off as u64);
        if n < 0 {
            return if off > 0 { off as i32 } else { n };
        }
        if n == 0 {
            break;
        }
        // `.min(len)` rather than a bare add: a driver reporting more than it was
        // asked for would otherwise walk `off` past the buffer and over-report the
        // write. Clamping keeps the reply bounded by what the client actually
        // handed over, whatever the driver says.
        off = off.saturating_add(n as usize).min(len);
    }
    off as i32
}

/// Reply to a SENDREC caller: stamp `m_type`, zero `m_source` (the kernel
/// overwrites it on delivery), and SEND the message back. A copy of TTY's, for
/// the reason TTY's exists.
#[cfg_attr(test, allow(dead_code))]
fn reply(target_e: Endpoint, msg: &mut Message, m_type: i32) {
    msg.m_type = m_type;
    msg.m_source = 0;
    let _ = ipc_send(target_e, msg);
}

