//! Unlike the demo stubs it replaces, `init` is a real boot module: it is packed
//! into the boot-image archive with its true proc number (`INIT_PROC_NR = 10`)
//! and loaded + made runnable by the ordinary boot loop
//! (`kernel/src/arch/aarch64/userland.rs`), not hand-released by PM. It runs as
//! an ordinary user process — the shared `USER_PRIV_ID` privilege (SENDREC to PM
//! only, no kernel calls) — so the whole process lifecycle flows through PM in
//! the POSIX shape (user → PM, never user → kernel).
//!
=== vfs main 230-320 ===
///
/// Then the grant. `caller_e` is the **kernel-stamped `m_source`** — the one fact
/// in this whole request a client cannot forge. VFS holds `SYS_PROC`, which is
/// what makes a magic grant legal for it; taking the owner from the payload
/// instead would let any VFS client aim TTY's privileged `SYS_SAFECOPY` at a
/// third party's address space through VFS. There is no payload field for it, and
/// there must never be one.
#[cfg_attr(test, allow(dead_code))]
fn do_write(
    caller_e: Endpoint,
    msg: &Message,
    grants: &mut GrantPool<GRANT_SLOTS>,
    tty: Endpoint,
) -> i32 {
    let minor = match fd::resolve(endpoint_proc(caller_e).get(), rd_i32(msg, VFS_FD_OFF)) {
        Ok(Fd::CharDev { minor }) => minor,
        // `resolve` maps a closed descriptor to `EBADF` itself, so this arm is
        // unreachable today. It exists so slice 5.8's regular-file variant shows
        // up as a compile error to be routed, not a silent fallthrough.
        Ok(Fd::Unused) => return EBADF,
        Err(e) => return e,
    };

    let len = rd_i32(msg, VFS_LEN_OFF);
    if len < 0 {
        return EINVAL;
    }
    let len = len as usize;
    if len == 0 {
        return 0;
    }

