1	// SPDX-License-Identifier: BSD-3-Clause
2	// Copyright (c) 2025-2026 Kevin Barnard and minix.rs Contributors
3	//! minix.rs VFS (virtual file system) server — the POSIX write path (slice 5.4),
4	//! plus the grant and console demos slices 5.2 and 5.3 left behind as regression
5	//! probes.
6	//!
7	//! Slice 4.2 stood VFS up as a real boot server: it boots through the SEF
8	//! framework and publishes its endpoint to DS. Slice 5.2 gave it the granting half
9	//! of the first cross-address-space copy ([`grant_test`]), and 5.3 made it the
10	//! first client of the TTY console driver ([`tty_demo`]).
11	//!
12	//! Slice 5.4 makes it a *file system* server, in the one sense that matters at
13	//! this stage: an ordinary user process can now write to a descriptor. See
14	//! [`do_write`].
15	//!
16	//! ## The write path, and its one copy
17	//!
18	//! ```text
19	//! user ──VFS_WRITE{fd,buf,len}──► VFS ──CDEV_WRITE{minor,gid,len,off}──► TTY
20	//!                                  │                                      │
21	//!                                  └── magic grant: caller's buf ──────────┘
22	//!                                          (kernel copies, once)
23	//! ```
24	//!
25	//! VFS resolves the descriptor, issues a **magic** (third-party) grant naming the
26	//! *caller's* buffer with the driver as grantee, and forwards the id. TTY then
27	//! safecopies straight out of the caller's address space into its staging buffer.
28	//! The bytes never pass through VFS — there is exactly one copy, from the process
29	//! that wrote them to the driver that transmits them, which is the whole point of
30	//! the D4 grant design.
31	//!
32	//! Three properties hold that path together, each of which has its own probe in
33	//! the boot log:
34	//!
35	//! **The grant's owner is the kernel-stamped `m_source`.** VFS holds `SYS_PROC`,
36	//! which is what makes a magic grant legal for it at all; a caller-supplied owner
37	//! field would therefore let *any* VFS client aim a privileged cross-address-space
38	//! copy at a third party's memory. `VFS_WRITE` has no such field. This is slice
39	//! 5.2/5.3's confused-deputy rule applied to the granting side.
40	//!
41	//! **VFS absorbs short writes.** `CDEV_MAX_IO` is a driver staging detail; a
42	//! `write()` return value is not allowed to expose it. So [`write_all`] re-sends
43	//! with `offset` advanced until the buffer is out and reports the total.
44	//!
45	//! **Every request gets a reply.** VFS's clients are all inside a SENDREC, so a
46	//! dropped message blocks the caller forever — TTY's rule, and now VFS's.
47	//!
48	//! Built as a freestanding aarch64 ELF (see `servers/vfs/user.ld`), packed into
49	//! the kernel's boot-image archive by `kernel/build.rs`, and loaded into its own
50	//! per-process AddrSpace at boot by `arch::aarch64::userland::load_boot_server`.
51	
52	// Freestanding for the real (bare-metal) build, but a normal host binary under
53	// `cargo test` (no host tests yet — the SEF/IPC glue is QEMU-verified). The
54	// `_start` shim and panic handler are gated to `not(test)`.
55	#![cfg_attr(not(test), no_std)]
56	#![cfg_attr(not(test), no_main)]
57	
58	minixrs_abi_note::brand!();
59	
60	mod fd;
61	mod write;
62	
63	use minixrs_ipc::{ipc_send, ipc_sendrec};
64	use minixrs_kernel_shared::Message;
65	use minixrs_kernel_shared::callnr::{
66	    CDEV_GRANT_OFF, CDEV_LEN_OFF, CDEV_MAX_IO, CDEV_MINOR_CONSOLE, CDEV_MINOR_OFF, CDEV_OFFSET_OFF,
67	    CDEV_WRITE, PM_GRANT_TEST, SYS_GETINFO_NAME_LEN, VFS_BUF_OFF, VFS_FD_OFF, VFS_LEN_OFF,
68	    VFS_WRITE,
69	};
70	use minixrs_kernel_shared::com::{PM_PROC_NR, TTY_PROC_NR, boot_endpoint};
71	use minixrs_kernel_shared::endpoint::{Endpoint, endpoint_proc};
72	use minixrs_kernel_shared::error::{EBADF, EFAULT, EINVAL, ENOSYS, ENXIO, EPERM, OK};
73	use minixrs_kernel_shared::grant::{CPF_READ, CPF_WRITE};
74	use minixrs_kernel_shared::message::user_range_ok;
75	use minixrs_server_rt::{
76	    GrantPool, SefConfig, diag_fmt, rd_i32, rd_u64, sef_publish_to_ds, sef_retrieve_from_ds,
77	    sef_startup, wr_i32, wr_u64,
78	};
79	
80	use fd::Fd;
81	
82	/// Bytes VFS grants PM in the slice-5.2 demo.
83	const GRANT_TEST_LEN: usize = 64;
84	
85	/// Number of simultaneously outstanding grants VFS can hold. VFS's stack is one
86	/// page, and the pool costs `N * 32` bytes; 8 is ample for the demo.
87	const GRANT_SLOTS: usize = 8;
88	
89	/// The granted buffer. A `static` (not `static mut`) so it lands in `.rodata`,
90	/// which the ELF loader maps read-only — exactly right for a `CPF_READ` grant,
91	/// and it means the kernel's `Prot::writable` check would reject any attempt to
92	/// safecopy *into* it.
93	static GRANT_TEST_BUF: [u8; GRANT_TEST_LEN] = grant_test_pattern();
94	
95	/// A deterministic, non-trivial byte pattern. Deterministic so PM's checksum is
96	/// a fixed value across runs; non-trivial (not `i`, not a constant) so a copy
97	/// that lost or duplicated a chunk still changes the sum.
98	const fn grant_test_pattern() -> [u8; GRANT_TEST_LEN] {
99	    let mut b = [0u8; GRANT_TEST_LEN];
100	    let mut i = 0;
101	    while i < GRANT_TEST_LEN {
102	        b[i] = (i as u8).wrapping_mul(37).wrapping_add(11);
103	        i += 1;
104	    }
105	    b
106	}
107	
108	// ----- Slice 5.3: the CDEV console demo ------------------------------------
109	
110	/// The line VFS asks TTY to print. In `.rodata` (a `static`, not `static mut`),
111	/// which the ELF loader maps read-only — exactly right for a `CPF_READ` grant.
112	static TTY_BANNER: [u8; 35] = *b"minix.rs vfs: hello via CDEV_WRITE\n";
113	
114	/// Length of the short-write probe: eight bytes past what one `CDEV_WRITE` can
115	/// carry, so the reply must come back clamped.
116	const TTY_RULE_LEN: usize = CDEV_MAX_IO + 8;
117	
118	/// A buffer deliberately longer than [`CDEV_MAX_IO`], whose byte at index
119	/// `CDEV_MAX_IO - 1` is `\n` — so the *clamped* write renders as exactly one
120	/// console line. The eight bytes past the clamp spell `TRUNCATE`, which therefore
121	/// must never appear on the console: if they do, the driver ignored its own limit.
122	static TTY_RULE: [u8; TTY_RULE_LEN] = tty_rule_pattern();
123	
124	const fn tty_rule_pattern() -> [u8; TTY_RULE_LEN] {
125	    let mut b = [b'-'; TTY_RULE_LEN];
126	    let prefix = b"minix.rs vfs: short-write rule ";
127	    let mut i = 0;
128	    while i < prefix.len() {
129	        b[i] = prefix[i];
130	        i += 1;
131	    }
132	    // Ends the line at the clamp boundary.
133	    b[CDEV_MAX_IO - 1] = b'\n';
134	    // Past the clamp: must never reach the console.
135	    let tail = b"TRUNCATE";
136	    let mut j = 0;
137	    while j < tail.len() {
138	        b[CDEV_MAX_IO + j] = tail[j];
139	        j += 1;
140	    }
141	    b
142	}
143	
144	/// ELF entry point. The kernel primes `SP_EL0` before `eret`, so `_start` can
145	/// dive straight into Rust without setting up a stack itself.
